head.script:
/**
 * 전역 변수
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.codeSeper   = '------------';  // 코드간 구분자
scwin.sbm_search_target = 'data:json,{"id":"dlt_csDvsCd","key":"data.dlt_csDvsCd"}';
scwin.cortCd = ssgo.getIntgStorage(ssgo.STORAGE.SGM_COND.ID, ssgo.STORAGE.SGM_COND.KIND.cortCd);
scwin.csDvsCd = ssgo.getIntgStorage(ssgo.STORAGE.SGM_COND.ID, ssgo.STORAGE.SGM_COND.KIND.csDvsCd);
scwin.title = '사건번호로 검색';
scwin.eachCortParam = {};

/**
 * 화면 pageload 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * 2025.11.13.   김윤수       [25A-SSG-0023] 웹접근성 심사 결과에 따른 조치
 * ============ ============ ==========================
 */
scwin.onpageload = function () {
    // 각급법원 파라메터
    scwin.eachCortParam   = com.data.getParameter() || ssgo.getParameter();

    ssgo.setDocumentTitle(scwin.title);
    
    // 사건번호직접입력 숨김
    ibx_fullCsNo.hide();
    //ibx_csSerial.focus();

    // 1. 화면 로드시 기본정보(코드등) 조회 submission
    scwin.sbm_selectCodeInfo();
    
    // 2. captcha정보 로드
    if(scutilo.isEmpty(scwin.eachCortParam.cortCd)
    && scutilo.isEmpty(scwin.eachCortParam.csYear)
    && scutilo.isEmpty(scwin.eachCortParam.csSerial)
    && scutilo.isEmpty(scwin.eachCortParam.btprtNm)
    && scutilo.isEmpty($p.getParameter("initTabYn"))
    ) {
        com.executeSubmission(sbm_captcha);

        // 4분마다 캡챠문자 갱신
        com.util.setInterval(
            function() {
                btn_reloadCaptcha.trigger("onclick");
            },
            { delay : 1000*60*4, key : "loginTimeout" }
        );        
    } else {
        img_captcha.hide();
    }
    
    // 3. 각 검색영역별 enter event add
    ssgo.setEnterKeyEventOfGrpObj(grp_srchCsNoFrom, scwin.btn_srchCs_onclick, "input");
    
    // 4. 조회이력
    var histStorage  = ssgo.STORAGE.SGM_HIST;
    var rcntCsHistMsg = "기존 사건검색 결과(최근 검색 사건 중 최대 "+ histStorage.MAX_CNT+"건까지 조회가능)";
    txt_rcntCsHistMsg.setValue(rcntCsHistMsg);

    // 5. 사건검색 OVERTIEM 스토리지삭제
    ssgo.removeSessionStorageSection("CS_SRCH_OVER_CHK");	// 사건검색 OVERTIEM 스토리지삭제
    ssgo.removeSessionStorageSection("LOGIN_INFO"); // 로그인정보 스토리지 삭제
};

/**
 * 화면 pageunload 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.onpageunload = function () {
};


/**
 *********************************************************************************************************
 * Submission Event Handler
 *********************************************************************************************************
 */

/**
 * SSGO(메모리) 관련 코드조회
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_selectCodeInfo = function() {

    dma_search.set("cortCd", scwin.cortCd);
    dma_search.set("cdScope", "ALL");   // 법원,사건구분 둘다 조회함

    var csNoHistLst = "";
    var dt_csHist = scwin.ufn_getStorageCsHistLst();
    if(!scutilo.isEmpty(dt_csHist)) {
        for(let i = 0; i < dt_csHist.length; i++) {
            csNoHistLst += dt_csHist[i].csYear + dt_csHist[i].csDvsCd + scutilo.getLPadding(dt_csHist[i].csSerial, 7, "0");
            if((i+1) != dt_csHist.length) {
                csNoHistLst += ",";
            }
        }
        dma_search.set("csNoHistLst", csNoHistLst);
    }
    
    com.executeSubmission(sbm_search);
};

/**
 * 코드 조회 submission done 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_search_submitdone = function(e) {

    // 화면최로드시에만 법원코드를 셋팅한다.
    if(sbm_search.target !== scwin.sbm_search_target) {
        // 1. 법원코드 셋팅 ---------------------------------
        dlt_dynamic_cortCd.removeAll();

        // js법원정보 셋팅
        ssgocbx.setCortCd(sbx_cortCd);
        
        // 2. 년도코드 셋팅 ---------------------------------
        var csYrdArr = [];
        var ymd      = $p.getCurrentServerDate("yyyyMM");
        var nowYr    = ymd.substring(0,4);
        for(var i = nowYr; i >= 1985; i--) {
            csYrdArr.push({"code" : i, "codeNm" : i});
        }
        csYrdArr.push({"code" : 1969, "codeNm" : 1969});    // 1969년 추가
        
        dlt_csYr.removeAll();
        dlt_csYr.setJSON(csYrdArr);
        dma_search.set("csYr", ymd.substring(0,4)); // 현재 사건년도 선택      
        
        // 3. 사건구분 셋팅 ----------------------------------
        dlt_dynamic_csDvsCd.removeAll();

        // js사건구분정보 셋팅
        ssgocbx.setCsDvsCd(sbx_csDvsCd, (scutilo.isEmpty(scwin.cortCd))? dlt_dynamic_cortCd.getCellData(0, "code") : scwin.cortCd );
        
    } else {
        
        // 사건구분 셋팅 ----------------------------------
        dlt_dynamic_csDvsCd.removeAll();
        dlt_dynamic_csDvsCd.setJSON(dlt_csDvsCd.getAllJSON());

        // 사건번호입력모드 trigger
        if(cbx_chkSanoInputMode.getValue() === "Y") {
            cbx_chkSanoInputMode.trigger("onchange");
        }

    }

    // localStorage에서 검색조건 조회
    scwin.ufn_changeStorageInputStatus('get');

    scwin.cbx_sortHangulCortCd_onchange();

    // 각급법원 사건검색 호출시 검색
    scwin.ufn_eachCort_srchCs(scwin.eachCortParam);

};    

/**
 * 코드 조회 submission error 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_search_submiterror = function(e) {
    ssgo.printSubmiterror(e);
};

/**
 * 캡챠정보 조회 submission done 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_captcha_submitdone = function(e) {
   
    const captcha = document.querySelector(".inp_searchbox.pt5");
    
    const image = dma_captchaInf.get("image");
    //const answer = dma_captchaInf.get("answer");

    const binary = ssgo.fixBinary(atob(image));
    const blob = new Blob([binary], { type: 'image/png' });

    const url = URL.createObjectURL(blob);     
    
    const img = captcha.querySelector("img");
    img.setAttribute('src', url);

}

/**
 * 캡챠정보 조회 submission error 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_captcha_submiterror = function(e) {
    ssgo.printSubmiterror(e);
};

/**
 *********************************************************************************************************
 * Event Handler
 *********************************************************************************************************
 */
/**
 * 사건번호입력모드 클릭 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 *  2025.11.13.   김윤수       [25A-SSG-0023] 웹접근성 심사 결과에 따른 조치
 * ============= ============ ==========================
 */
scwin.cbx_chkSanoInputMode_onchange = function(info) {
    if( cbx_chkSanoInputMode.getValue() === "Y" ) {
        dma_search.set("fullCsNo","");
        ibx_fullCsNo.show("");
        sbx_csYr.hide();
        sbx_csDvsCd.hide();
        ibx_csSerial.hide();
        //ibx_fullCsNo.focus();
    } else {
        ibx_fullCsNo.hide();
        sbx_csYr.show("");
        sbx_csDvsCd.show("");
        ibx_csSerial.show("");
        //ibx_csSerial.focus();
    }
};

/**
 * 검색버튼 클릭 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_srchCs_onclick = function() {

    //dma 정상 세팅을 위한 focus 처리
    btn_srchCs.focus();

    // 정합성 체크
    if(!scwin.vfn_validateCsSrch()) {
        return false;
    }

	var param = {
        cortCd        : dma_search.get("cortCd"),      // 법원코드
        cortNm        : sbx_cortCd.getText(),       // 법원명
        csYear        : dma_search.get("csYr"),        // 사건년도
        csDvsCd       : dma_search.get("csDvsCd"),     // 사건구분
        csDvsNm       : sbx_csDvsCd.getText(),      // 사건구분명
        csSerial      : dma_search.get("csSerial"),    // 사건시리얼번호
	    btprtNm       : dma_search.get("btprNm"),      // 당사자명
        fullCsNo      : dma_search.get("fullCsNo"),    // 사건번호(FULL)        
	    captchaAnswer : dma_search.get("answer"),      // 캡챠번호
        encCaptchaAnswer : dma_captchaInf.get("answer"),   // 캡챠번호
        saveCsRsltYn  : cbx_saveCsRsltYn.getValue(), // 사건정보 이력저장 여부
        comTaskTypCd  : dlt_dynamic_csDvsCd.getCellData(sbx_csDvsCd.getSelectedIndex(), "comTaskTypCd"), // 재판사무업무유형코드
        isMain        : 'Y',
	};
    
    // 필터조건을 로컬스토리지에 저장함.
    scwin.ufn_changeStorageInputStatus('set');

    com.win.moveUrl(ssgo.getCtxtPathUrl(ssgo.getProperties("clt.ssgo.rslt.csinfo")), param);
};


/**
 * 자동입력방지(캡챠) 이미지 리로딩
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_reloadCaptcha_onclick = function(e) {
    com.executeSubmission(sbm_captcha);
};

/**
 * 캡챠 음성듣기
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_voiceListen_onclick = function(e) {
    if(!scutilo.isEmpty(dma_captchaInf) && dma_captchaInf.get("audio")){
        const binary = ssgo.fixBinary(atob(dma_captchaInf.get("audio")));
        const blob = new Blob([binary], { type: 'audio/wave' });
        const url = URL.createObjectURL(blob);
        new Audio(url).play();
    }    
};

/**
 * 법원코드 onchange 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.sbx_cortCd_onchange = function(info) {
    
    scwin.cortCd = info.newValue;

    // js사건구분정보 셋팅
    dlt_dynamic_csDvsCd.removeAll();
    ssgocbx.setCsDvsCd(sbx_csDvsCd, sbx_cortCd.getValue());

    scwin.cbx_sortHangulCortCd_onchange();
};

/**
 * 법원코드 한글정렬 체크박스 onchange 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.cbx_sortHangulCortCd_onchange = function(info) {
    sbx_cortCd.setEventPause(null, true);   // event lock

    // 체크시
    if( cbx_sortHangulCortCd.getValue() === "Y" ) {
        // 구분자(------) 삭제처리
        for(let i = 0; i < dlt_dynamic_cortCd.getRowCount(); i++) {
            let code   = dlt_dynamic_cortCd.getCellData(i, dlt_dynamic_cortCd.cellIdList[0]);
            //let codeNm = dlt_dynamic_cortCd.getCellData(i, dlt_dynamic_cortCd.cellIdList[1]);
            
            // A로 시작하는 구분자코드를 삭제
            if(code.substring(0,1) === "A") {
                dlt_dynamic_cortCd.removeRow(i);
            }
        }
        
        dlt_dynamic_cortCd.sort(dlt_dynamic_cortCd.cellIdList[1], 0);                   // 한글 오름차순 정렬
        dlt_dynamic_cortCd.setJSON(scwin.ufn_addseperInDatalist(dlt_dynamic_cortCd));   //다른 초성사이에 구분자 add
    // 체크해제시    
    } else if( cbx_sortHangulCortCd.getValue() !== "Y" ) {

        dlt_dynamic_cortCd.removeAll();

        // js법원정보 셋팅
        ssgocbx.setCortCd(sbx_cortCd);

    }

    sbx_cortCd.setEventPause(null, false);  // event unlock

    scwin.cbx_sortHangulCsDvsCd_onchange();

};

/**
 * 사건구분 한글정렬 체크박스 onchange 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.cbx_sortHangulCsDvsCd_onchange = function(info) {

    // 선택된 사건구분정보 유지처리
    var storage  = ssgo.STORAGE;
    var condId   = storage.SGM_COND.ID;
    var condKind = storage.SGM_COND.KIND;
    var sessDvsCd = ssgo.getIntgStorage(condId, condKind.csDvsCd);
    var csDvsCdVal = !scutilo.isEmpty(sessDvsCd) ? sessDvsCd : scwin.csDvsCd;

    // 체크시
    if( cbx_sortHangulCsDvsCd.getValue() === "Y" ) {

        // 구분자(------) 삭제처리
        for(let i = 0; i < dlt_dynamic_csDvsCd.getRowCount(); i++) {
            let code   = dlt_dynamic_csDvsCd.getCellData(i, dlt_dynamic_csDvsCd.cellIdList[0]);
            let codeNm = dlt_dynamic_csDvsCd.getCellData(i, dlt_dynamic_csDvsCd.cellIdList[1]);

            if(code.substring(0,1) === "A" || scutilo.isEmpty(code)) {
                dlt_dynamic_csDvsCd.removeRow(i);
            }
        }

        dlt_dynamic_csDvsCd.sort(dlt_dynamic_csDvsCd.cellIdList[1], 0);              // 한글 오름차순 정렬
        dlt_dynamic_csDvsCd.setJSON(scwin.ufn_addseperInDatalist(dlt_dynamic_csDvsCd)); //다른 초성사이에 구분자 add

    // 체크해제시    
    } else if( cbx_sortHangulCsDvsCd.getValue() !== "Y" ) {
        dlt_dynamic_csDvsCd.removeAll();
        
        // js사건구분정보 셋팅
        ssgocbx.setCsDvsCd(sbx_csDvsCd, (scutilo.isEmpty(scwin.cortCd))? dlt_dynamic_cortCd.getCellData(0, "code") : scwin.cortCd );
    }

    sbx_cortCd.setEventPause(null, true);   // event lock
    dma_search.set("cortCd", scwin.cortCd);
    sbx_cortCd.setEventPause(null, false);  // event unlock

    var checkVal = dlt_dynamic_csDvsCd.getMatchedData("csDvsCd", csDvsCdVal, true);
    if(checkVal.length == 0){
        sbx_csDvsCd.setSelectedIndex(0);
    }else {
        dma_search.set("csDvsCd", csDvsCdVal);
    }
    
};

/**
 * 사건검색이력 전체선택
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_csSrchHistAllChk_onclick = function(e) {
    csSrchRsltGrid.checkAll(0, 1);
};

/**
 * 사건검색이력 전체선택 해제
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_csSrchHistAllUnChk_onclick = function(e) {
    csSrchRsltGrid.checkAll(0, 0);
};

/**
 * 사건검색이력 사건번호 선택
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.csSrchRsltGrid_oncellclick = function(row,col,colId) {
    var dltObj = com.util.getGridViewDataList(this);
    var realRowIndex = this.getRealRowIndex(row);
    var newValue = dltObj.getCellData(realRowIndex, col);

    // 사건번호 Cell 클릭시 
    if (newValue != "" && col == 2) {
        var param = dltObj.getRowJSON(row);
        
        param.csNo = param.csYear + param.csDvsCd + scutilo.getLPadding(param.csSerial, 7, "0");
        param.captchaAnswer = '';   // 캡챠정보 삭제
        param.srchDvs = '06';     // 검색이력목록후사건번호검색(조회결과있을시)
        param.saveCsRsltYn = cbx_saveCsRsltYn.getValue();   // 사건검색 결과 저장 여부

        // 필터조건을 로컬스토리지에 저장함.
        scwin.ufn_changeStorageInputStatus('set');

        com.win.moveUrl(ssgo.getCtxtPathUrl(ssgo.getProperties("clt.ssgo.rslt.csinfo")), param);        
    }
};

/**
 * 검색이력 목록 삭제
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_csSrchHistDel_onclick = function(e) {
    var storage = ssgo.STORAGE.SGM_HIST;
    var jsonCsHist = ssgo.decode(com.storage.get(storage.ID, storage.KIND.mainCsHist));
    var arrCsHIst = scutilo.isEmpty(jsonCsHist) ? "" : JSON.parse(jsonCsHist);
   
    // 체크된 이력정보 조회
    var delCsSrchHist = dlt_csSrchHistList.getMatchedIndex("chk", "1");

    btn_csSrchHistDel.focus();

    if(delCsSrchHist.length === 0) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0008), function (result) {
            
            var focusTime = setInterval(function() {

                btn_csSrchHistDel.focus();
                clearTimeout(focusTime);
            }, 100);

        });

        return;
    }
    
    // 전체삭제 처리
    if(dlt_csSrchHistList.getRowCount() == delCsSrchHist.length) {
        dlt_csSrchHistList.removeAll();
        com.storage.removeSection(storage.ID);
        com.storage.removeSection("STORAGE_CONFIG");

        var focusTime = setInterval(function() {

            btn_csSrchHistDel.focus();
            clearTimeout(focusTime);
        }, 100);

        
        return;
    }
    
    // 선택된 사건이력 데이터리스트 삭제
    dlt_csSrchHistList.removeRows(delCsSrchHist);   // 삭제 Row
    
    // 삭제처리된 Index를 storage에서 찾아 같이 삭제한다.
    var arrCsHistCnt = arrCsHIst.length-1;
    for(let i = arrCsHistCnt; i >= 0; i--) {
        for(let j = 0; j < delCsSrchHist.length; j++) {
            if(i == (arrCsHistCnt-delCsSrchHist[j])) {
                arrCsHIst.splice(i,1);
            }
        }
    }
 
    // storage 모두삭제 후 재저장
    com.storage.removeSection(storage.ID);
    com.storage.set(storage.ID, storage.KIND.mainCsHist, ssgo.encode(JSON.stringify(arrCsHIst)));
    com.storage.set("STORAGE_CONFIG", "MAXAGE", ssgo.encode(new Date().getTime())); // 스토리지 갱신

    var focusTime = setInterval(function() {

        btn_csSrchHistDel.focus();
        clearTimeout(focusTime);
    }, 100);

};


