/**
 * 사건검색 검색조건 정합성 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 *  2025.07.17.   김윤수       [25A-SSG-0016] 당사자명에 포함된 특수문자(:)를 검색 가능한 문자로 수정
 * ============= ============ ==========================
 */
scwin.vfn_validateCsSrch = function() {

    // 사건번호 입력모드 정합성체크
    if(cbx_chkSanoInputMode.getValue() === "Y" && !scwin.ufn_textToSbxCsNo()) return false;
    
    var csSerial  = dma_search.get("csSerial");
    var btprNm    = dma_search.get("btprNm");
    var answer    = dma_search.get("answer");
    var csDvsCd    = dma_search.get("csDvsCd");

    if( csDvsCd.indexOf("A") === 0 ) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0002, "법원을"), function() {  //I_0002: "법원을 선택하십시오."

            var focusTime = setInterval(function() {

                sbx_cortCd.focus();
                clearTimeout(focusTime);
            }, 100);
            
        });
        return false; 
    }
    
    if( csDvsCd.indexOf("A") === 0 || scutilo.isEmpty(csDvsCd)) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0002, "사건구분을"), function() {  //I_0002: "사건구분을 선택하십시오."
            
            var focusTime = setInterval(function() {

                sbx_csDvsCd.focus();
                clearTimeout(focusTime);
            }, 100);

        });
        return false; 
    }

    csSerial = csSerial.replace(/^\s*|\s*$/g, '');
    dma_search.set("csSerial", csSerial);

    if(scutilo.isEmpty(csSerial)) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0001, "사건일련번호를"), function() {  //I_0001: "사건일련번호를 입력하십시오."
            
            var focusTime = setInterval(function() {

                ibx_csSerial.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false; 
    }

    // [사건검색]홈페이지 사건검색 금칙어 처리
    btprNm = btprNm.replace(/\s/g, '');
    if(btprNm === "당사자명필수입력" || btprNm.length < 2 ) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0001, "당사자명을 2자이상"), function() {  //I_0001: "당사자명을 2자이상을 입력하십시오."
            
            var focusTime = setInterval(function() {

                ibx_btprNm.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false; 
    }
    dma_search.set("btprNm", btprNm);

    var  anum=/(^\d+$)|(^\d+\.\d+$)/  

    if(!anum.test(csSerial)) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0003, "사건일련번호는"), function() {  //I_0003: "당사자명에 특수문자는 사용할 수 없습니다."
            
            var focusTime = setInterval(function() {
                dma_search.set("csSerial", "");
                ibx_csSerial.focus();
                clearTimeout(focusTime);
            }, 100);

        });
        return false; 
    }

    // [25A-SSG-0016] 당사자명에 포함된 특수문자(:)를 검색 가능한 문자로 수정
    var filter_word = /[$\\\\#\%\^\&\*\+\_\`\~\=\|\,\'\"\-\;\％\/]/;  //특수문자를 배열
    if (btprNm.search(filter_word)>=0) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0004, "당사자명에"), function() {  //I_0004: "당사자명에 특수문자는 사용할 수 없습니다."
            
            var focusTime = setInterval(function() {
                dma_search.set("btprNm","");
                ibx_btprNm.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false; 
    }

    // 대법원 홈페이지 사건검색에서 금칙어를 사용 할 수 없도록 처리
    var psBanWordList = ssgo.getProperties("clt.ssgo.ban.word.list");
    var lines = psBanWordList.split(",");

    // 홈페이지 사건검색 금칙어 처리
    if( psBanWordList.indexOf(btprNm)>=0 ) {
        // 금칙어 추가 및 메세지 처리
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0005, btprNm, btprNm), function() {  //I_0005 : "[btprNm]만 입력하는 경우 검색이 제한됩니다.\n" + "당사자명 전부를 입력하거나, [btprNm] 이외의 부분을 추가로 입력하시기 바랍니다.\n" + "당사자명이 2자인 경우, 사건상대방의 이름을 입력하여 조회하시기 바랍니다."
            
            var focusTime = setInterval(function() {
                ibx_btprNm.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false; 
    }

    answer = answer.replace(/\s/g, '');
    if ( answer.length != 6 ) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0001, "자동입력 방지 문자 6자를"), function() {  //I_0001: "자동입력 방지 문자 6자를 입력하십시오."
            
            var focusTime = setInterval(function() {
                ibx_answer.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false;
    }    
    
    // 캡챠암호화 문자체크
    var encAnswer = dma_captchaInf.get("answer");
    if(scutilo.isEmpty(encAnswer)) {
        
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.E_0007, "캡챠 랜더링"), function () { //I_0001: "캡챠 랜더링 처리 중 오류가 발생하였습니다."
        });
        
        return false;
    }
    return true;
}

