/**
 * 코드명 초성이 다를때 구분자 Add
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_addseperInDatalist = function(dataList) {
    var rtnDataList = [];
    
    var aftChosung = "";
    var choSung = "";
    
    var keyNm   = dataList.cellIdList[0];   // key
    var valueNm = dataList.cellIdList[1];   // value
    
    for(let i = 0; i < dataList.getRowCount(); i++) {
        choSung = scwin.ufn_getChosung(dataList.getCellData(i, valueNm));
        if(choSung != aftChosung) {
            if(i != 0){
                rtnDataList.push({[keyNm] : "A0"+i, [valueNm] : scwin.codeSeper});
            }	
            aftChosung = choSung;
        }
        rtnDataList.push(dataList.getRowJSON(i));
    }

    //기존코드 삭제
    dataList.removeAll();   
    
    return rtnDataList;
}



/**
 * 초성정보를 조회한다.
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_getChosung = function(str) {
  
  var choWord = ["ㄱ","ㄲ","ㄴ","ㄷ","ㄸ","ㄹ","ㅁ","ㅂ","ㅃ","ㅅ","ㅆ","ㅇ","ㅈ","ㅉ","ㅊ","ㅋ","ㅌ","ㅍ","ㅎ"];
  var rtnChoSung = "";
  var code = "";

  if(str.length > 0) {
    code = str.charCodeAt(0)-44032;
    if(code>-1 && code<11172) rtnChoSung += choWord[Math.floor(code/588)];
    else rtnChoSung += str.charAt(0);  
  }

  return rtnChoSung;
}

/**
 * 사건번호(입력모드) 검증 
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_textToSbxCsNo = function() {
    var pos = 0;
    var year = "";
    var csDvs = "";
    var saSerial = "";
    var tmpStr = ""
    var iscsDvsCd = false;
    var saNo = dma_search.get("fullCsNo");

    if(scutilo.isEmpty(saNo)) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0001, "사건번호를"), function() {  //I_0001: "사건번호를 입력하십시오.",
            
            var focusTime = setInterval(function() {
                ibx_fullCsNo.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false;
    }

    saNo = saNo.replace(/\s/g, '');

    for (let i=0;i< saNo.length ; i++ ) {
        if (saNo.charAt(i) < "0" || saNo.charAt(i) > "9") {
            pos = i;
            break;
        }
    }

    // 년도체크
    year  = scwin.ufn_getYear(saNo.substr(0, pos));
    if (year.length !== 4) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0006, "년도를"), function () { //I_0006 : "올바른 년도를 입력하세요."
        });
        return false;
    }
    dma_search.set("csYr", year);
    
    // 사건구분 체크
    tmpStr = saNo.substr(pos,saNo.length);
    for (let i=0;i< tmpStr.length ; i++ ) {
        if (tmpStr.charAt(i) >= "0" && tmpStr.charAt(i) <= "9") {
            pos = i;
            break;
        }
    }
    csDvs = tmpStr.substr(0,pos);
    
    for(let i = 0; i < dlt_dynamic_csDvsCd.getRowCount(); i++) {
       if(csDvs === dlt_dynamic_csDvsCd.getCellData(i, dlt_dynamic_csDvsCd.cellIdList[1])) {
           sbx_csDvsCd.setSelectedIndex(i);
           iscsDvsCd = true;
           break;
       }
    }

    if( !iscsDvsCd ) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0006, "사건구분을"), function () { //I_0006 : "올바른 사건구분을 입력하세요."
        });
        return false;
    }

    // 사건일련번호 체크
    saSerial = tmpStr.substr(pos, tmpStr.length);
    if (scutilo.isEmpty(saSerial) || saSerial.length > 7) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0006, "사건번호를"), function () { //I_0006 : "올바른 사건번호를 입력하세요."
        });
        return false;
    }
    dma_search.set("csSerial", saSerial);

    return true;    
}

/**
 * 년도 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_getYear = function(year) {
    var iYear = 0;
    year = year.replace(/\s/g, '');

    if (year.length !== 2 && year.length !== 4) {
        return "";
    }

    for (let i=0; i< year.length ; i++ ) {
        if ( year.charAt(i) < "0" || year.charAt(i) > "9" ) {
            return "";
        }
    }
    iYear = parseInt(year, 10);

    if (year.length === 2) {
        if(iYear >= 50) {
            iYear = iYear + 1900;
        } else {
            iYear = iYear + 2000;
        }
    }

    var ymd    = $p.getCurrentServerDate("yyyyMM");
    var nowYr  = ymd.substring(0,4);
    
    if(iYear > nowYr) {
        return "";
    } else {
        return iYear.toString();
    }
}

/**
 * 로컬스토리지에 화면의 검색조건(필터)의 값(상태)를 조회 및 저장
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_changeStorageInputStatus = function(type) {
    var storage  = ssgo.STORAGE;
    var condId   = storage.SGM_COND.ID;
    var condKind = storage.SGM_COND.KIND;

    if(type === "set") {
        com.storage.set(condId, condKind.sortHangulCortCd,    cbx_sortHangulCortCd.getValue());   // 법원명 가나다순 정렬
        com.storage.set(condId, condKind.sortHangulCsDvsCd,   cbx_sortHangulCsDvsCd.getValue());  // 사건구분 가나다순 정렬
        com.storage.set(condId, condKind.saveCsRsltYn,        cbx_saveCsRsltYn.getValue());       // 사건검색 결과 저장
        com.storage.set(condId, condKind.chkSanoInputMode,    cbx_chkSanoInputMode.getValue());   //사건번호입력모드
    
    }else if(type === "get") {
        
        // 법원명 가나다순 정렬
        if(com.storage.get(condId, condKind.sortHangulCortCd) === "Y") {
            cbx_sortHangulCortCd.setSelectedIndex(0);
        }
        // 사건구분 가나다순 정렬
        if(com.storage.get(condId, condKind.sortHangulCsDvsCd) === "Y") {
            cbx_sortHangulCsDvsCd.setSelectedIndex(0);
        }

        // 사건검색 결과 저장
        if(com.storage.get(condId, condKind.saveCsRsltYn) === "Y") {
            cbx_saveCsRsltYn.setSelectedIndex(0);
        }

        // 사건번호입력모드
        if(com.storage.get(condId, condKind.chkSanoInputMode) === "Y") {
            cbx_chkSanoInputMode.setSelectedIndex(0);
        }

        // 법원
        if(!scutilo.isEmpty(ssgo.getIntgStorage(condId, condKind.cortCd))) {
            dma_search.set("cortCd", ssgo.getIntgStorage(condId, condKind.cortCd));
        }
        // 년도
        if(!scutilo.isEmpty(ssgo.getIntgStorage(condId, condKind.csYr))) {
            dma_search.set("csYr", ssgo.getIntgStorage(condId, condKind.csYr));
        }
        // 사건구분
        if(!scutilo.isEmpty(ssgo.getIntgStorage(condId, condKind.csDvsCd))) {
            dma_search.set("csDvsCd", ssgo.getIntgStorage(condId, condKind.csDvsCd));
        }

        // 사건시리얼번호
        if(!scutilo.isEmpty(ssgo.getIntgStorage(condId, condKind.csSerial))) {
            dma_search.set("csSerial", ssgo.getIntgStorage(condId, condKind.csSerial));
        }

        // 당사자명
        if(!scutilo.isEmpty(ssgo.getIntgStorage(condId, condKind.btprtNm))) {
            dma_search.set("btprNm",ssgo.getIntgStorage(condId, condKind.btprtNm));
        }

        // full사건번호
        if(!scutilo.isEmpty(ssgo.getIntgStorage(condId, condKind.fullTxtCsNo))) {
            dma_search.set("fullCsNo",ssgo.getIntgStorage(condId, condKind.fullTxtCsNo));
        }

        // 스토리지 생명주기 관리
        ssgo.setStorageLifeCycle();

        // 사건조회이력 조회
        dlt_csSrchHistList.removeAll();
        
        // localstorage 사건이력 조회
        var dt_csHist = scwin.ufn_getStorageCsHistLst();
        
        if(!scutilo.isEmpty(dt_csHist)) {
            for(let i = 0; i < dt_csHist.length; i++) {
                // index 셋팅
                dt_csHist[i].idx = i;

                // 암호화된 csNo셋팅
                for(let j = 0; j < dlt_csNoHistLst.getRowCount(); j++) {
                    let csNo = dt_csHist[i].csYear + dt_csHist[i].csDvsCd + scutilo.getLPadding(dt_csHist[i].csSerial, 7, "0");
                    if(csNo == dlt_csNoHistLst.getCellData(j, "csNo")) {
                        dt_csHist[i].encCsNo = dlt_csNoHistLst.getCellData(j, "encCsNo");
                    }
                }

                var comTaskTypCd = ssgo.getProperties("ctt.csDvsCd."+dt_csHist[i].csDvsCd);
                
                // 형사공판, 과태료사건인 경우 사건명을 보이지 않도록 처리
                if(comTaskTypCd == "HG" || comTaskTypCd == "GW") {
                    dt_csHist[i].csNm = "";
                }

                // 법원명 가공
                if ( dt_csHist[i].cortNm == "서울고법춘천재판부") {
                    dt_csHist[i].cortNm = "서울고법(춘천)";
                } else if (dt_csHist[i].cortNm == "대전고법청주재판부") {
                    dt_csHist[i].cortNm = "대전고법(청주)";
                } else if (dt_csHist[i].cortNm == "부산고법창원재판부") {
                    dt_csHist[i].cortNm = "부산고법(창원)";
                } else if (dt_csHist[i].cortNm == "부산고법울산재판부") {
                    dt_csHist[i].cortNm = "부산고법(울산)";
                } else if (dt_csHist[i].cortNm == "광주고법제주재판부") {
                    dt_csHist[i].cortNm = "광주고법(제주)";
                } else if (dt_csHist[i].cortNm == "광주고법전주재판부") {
                    dt_csHist[i].cortNm = "광주고법(전주)";
                } else if (dt_csHist[i].cortNm == "부산지법가정지원") {
                    dt_csHist[i].cortNm = "부산가정법원";
                } else if (dt_csHist[i].cortNm == "대구지법서부지원") {
                    dt_csHist[i].cortNm = "대구지방법원 서부지원";
                } else if (dt_csHist[i].cortNm == "부산지법동부지원") {
                    dt_csHist[i].cortNm = "부산지방법원 동부지원";
                } else if (dt_csHist[i].cortNm == "부산지법서부지원") {
                    dt_csHist[i].cortNm = "부산지방법원 서부지원";
                } else if (dt_csHist[i].cortNm == "대전지법가정지원") {   
                    dt_csHist[i].cortNm = "대전가정법원";
                } else if (dt_csHist[i].cortNm == "대구지법가정지원") {   
                    dt_csHist[i].cortNm = "대구가정법원";
                } else if (dt_csHist[i].cortNm == "광주지법가정지원") {   
                    dt_csHist[i].cortNm = "광주가정법원";
                } else if (dt_csHist[i].cortNm == "홍성지원") {   
                    dt_csHist[i].cortNm = "대전지방법원 홍성지원";
                } else if (dt_csHist[i].cortNm == "공주지원") {   
                    dt_csHist[i].cortNm = "대전지방법원 공주지원";
                } else if (dt_csHist[i].cortNm == "논산지원") {   
                    dt_csHist[i].cortNm = "대전지방법원 논산지원";
                } else if (dt_csHist[i].cortNm == "서산지원") {   
                    dt_csHist[i].cortNm = "대전지방법원 서산지원";
                } else if (dt_csHist[i].cortNm == "천안지원") {   
                    dt_csHist[i].cortNm = "대전지방법원 천안지원";
                } else if (dt_csHist[i].cortNm == "안동지원") {   
                    dt_csHist[i].cortNm = "대구지방법원 안동지원";
                } else if (dt_csHist[i].cortNm == "경주지원") {   
                    dt_csHist[i].cortNm = "대구지방법원 경주지원";
                } else if (dt_csHist[i].cortNm == "포항지원") {   
                    dt_csHist[i].cortNm = "대구지방법원 포항지원";
                } else if (dt_csHist[i].cortNm == "김천지원") {   
                    dt_csHist[i].cortNm = "대구지방법원 김천지원";
                } else if (dt_csHist[i].cortNm == "상주지원") {   
                    dt_csHist[i].cortNm = "대구지방법원 상주지원";
                } else if (dt_csHist[i].cortNm == "의성지원") {   
                    dt_csHist[i].cortNm = "대구지방법원 의성지원";
                } else if (dt_csHist[i].cortNm == "영덕지원") {   
                    dt_csHist[i].cortNm = "대구지방법원 영덕지원";
                } else if (dt_csHist[i].cortNm == "목포지원") {   
                    dt_csHist[i].cortNm = "광주지방법원 목포지원";
                } else if (dt_csHist[i].cortNm == "장흥지원") {   
                    dt_csHist[i].cortNm = "광주지방법원 장흥지원";
                } else if (dt_csHist[i].cortNm == "순천지원") {   
                    dt_csHist[i].cortNm = "광주지방법원 순천지원";
                } else if (dt_csHist[i].cortNm == "해남지원") {   
                    dt_csHist[i].cortNm = "광주지방법원 해남지원";
                } else if (dt_csHist[i].cortNm == "당진군법원") {   
                    dt_csHist[i].cortNm = "당진시법원";
                } else if (dt_csHist[i].cortNm == "연기군법원") {   
                    dt_csHist[i].cortNm = "세종특별자치시법원";
                }  
            }
            
        }
        
        dlt_csSrchHistList.setJSON(dt_csHist);
        
        // 사건검색이력 정렬(최신순으로)
        dlt_csSrchHistList.sort("idx", 1);

    }
}


/**
 * 로컬스토리지의 사건검색 이력조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_getStorageCsHistLst = function() {

    var storage  = ssgo.STORAGE;
    var condId   = storage.SGM_COND.ID;
    var condKind = storage.SGM_COND.KIND;
    
    var jsonCsHist = ssgo.decode(com.storage.get(storage.SGM_HIST.ID, storage.SGM_HIST.KIND.mainCsHist));
    var dt_csHist = scutilo.isEmpty(jsonCsHist) ? "" : JSON.parse(jsonCsHist);

    return dt_csHist;
}    


/**
 * 각급법원 사건검색 호출시 검색
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_eachCort_srchCs = function(eachCortParam) {

    if(!scutilo.isEmpty(eachCortParam.cortId)
    && !scutilo.isEmpty(eachCortParam.cortCd)
    && !scutilo.isEmpty(eachCortParam.csYear)
    && !scutilo.isEmpty(eachCortParam.csDvsCd)
    && !scutilo.isEmpty(eachCortParam.csSerial)
    && !scutilo.isEmpty(eachCortParam.btprtNm)
    && !scutilo.isEmpty(eachCortParam.captchaAnswer)
    ) {
        if(scutilo.isEmpty(eachCortParam.comTaskTypCd)){
           eachCortParam.comTaskTypCd = ssgo.getProperties("ctt.csDvsCd."+eachCortParam.csDvsCd);
        }
        var param = {
            cortCd        : eachCortParam.cortCd,      // 법원코드
            csYear        : eachCortParam.csYear,        // 사건년도
            csDvsCd       : eachCortParam.csDvsCd,     // 사건구분
            csSerial      : eachCortParam.csSerial,    // 사건시리얼번호
            btprtNm       : eachCortParam.btprtNm,      // 당사자명
            fullCsNo      : eachCortParam.fullCsNo,    // 사건번호(FULL)        
            captchaAnswer : eachCortParam.captchaAnswer,    // 캡챠번호
            encCaptchaAnswer : eachCortParam.encCaptchaAnswer,   // 암호화캡챠
            saveCsRsltYn  : 'N', // 사건정보 이력저장 여부
            comTaskTypCd  : eachCortParam.comTaskTypCd, // 재판사무업무유형코드
            isMain        : 'Y',
        };
        com.win.moveUrl(ssgo.getCtxtPathUrl(ssgo.getProperties("clt.ssgo.rslt.csinfo")), param);    
    }
}
